// src/LandingPage.js
import React, { useEffect } from "react";
import { Link } from "react-router-dom";
import { useAuth } from "./context/AuthContext";
import "./styles.css";

const LandingPage = () => {
  const { user, logout } = useAuth();

  useEffect(() => {
    const handleSmoothScroll = (e) => {
      if (e.target.getAttribute("href")?.startsWith("#")) {
        e.preventDefault();
        const target = document.querySelector(e.target.getAttribute("href"));
        if (target) {
          target.scrollIntoView({ behavior: "smooth", block: "start" });
        }
      }
    };

    document.querySelectorAll('a[href^="#"]').forEach((anchor) => {
      anchor.addEventListener("click", handleSmoothScroll);
    });

    const observerOptions = {
      threshold: 0.1,
      rootMargin: "0px 0px -100px 0px",
    };

    const observer = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          entry.target.classList.add("visible");
        }
      });
    }, observerOptions);

    document.querySelectorAll(".fade-in").forEach((el) => {
      observer.observe(el);
    });

    const handleScroll = () => {
      const navbar = document.querySelector(".navbar");
      if (!navbar) return;
      navbar.style.background =
        window.scrollY > 100 ? "rgba(10,10,10,0.95)" : "rgba(10,10,10,0.9)";
    };

    window.addEventListener("scroll", handleScroll);

    return () => {
      document.querySelectorAll('a[href^="#"]').forEach((anchor) => {
        anchor.removeEventListener("click", handleSmoothScroll);
      });
      window.removeEventListener("scroll", handleScroll);
    };
  }, []);

  return (
    <>
      <div className="bg-pattern"></div>

      {/* Navigation */}
      <nav className="navbar">
        <div className="nav-container">
          <div className="logo">CodeGen4Future</div>
          <ul className="nav-menu">
            <li>
              <Link to="/about" className="nav-btn">
                About
              </Link>
            </li>
            <li>
              <Link to="/problems" className="nav-btn">
                Problems
              </Link>
            </li>
            <li>
              <Link to="/contests" className="nav-btn">
                Contests
              </Link>
            </li>
            <li>
              <Link to="/leaderboard" className="nav-btn">
                Leaderboard
              </Link>
            </li>

            {user ? (
              <>
                <li>
                  <Link to="/profile" className="nav-btn">
                    Profile
                  </Link>
                </li>
                <li>
                  <span className="nav-user-text">
                    Hi, {user.username || user.email}
                  </span>
                </li>
                <li>
                  <button className="btn-logout" onClick={logout}>
                    Logout
                  </button>
                </li>
              </>
            ) : (
              <>
                <li>
                  <Link to="/login" className="nav-btn">
                    Login
                  </Link>
                </li>
                <li>
                  <Link to="/register" className="nav-btn">
                    Register
                  </Link>
                </li>
              </>
            )}
          </ul>
        </div>
      </nav>

      {/* Hero Section */}
      <section className="hero">
        <div className="hero-content">
          <h1>Code, Compete, Conquer — Anywhere.</h1>
          <p>The future of coding is in your browser.</p>

          <div
            className="cta-buttons"
            style={{
              marginTop: "20px",
              display: "flex",
              gap: "12px",
              flexWrap: "wrap",
              justifyContent: "center",
            }}
          >
            <Link to="/problems" className="btn btn-primary">
              Problems
            </Link>

            <Link to="/simple-editor" className="btn btn-secondary">
              Start Coding
            </Link>

            <Link to="/contests" className="btn btn-primary">
              Contests
            </Link>

            <Link to="/duel" className="btn btn-primary">
              1 vs 1 Duel
            </Link>

            <Link to="/teams" className="btn btn-primary">
              Team Battles
            </Link>

            {/* Learn more goes to About page */}
            <Link to="/about" className="btn btn-secondary">
              Learn More
            </Link>
          </div>
        </div>
      </section>

      {/* Floating Words */}
      <div className="floating-words">
        <span
          className="word"
          style={{ "--delay": "0s", "--x": "10%", "--y": "15%" }}
        >
          function
        </span>
        <span
          className="word"
          style={{ "--delay": "2s", "--x": "85%", "--y": "25%" }}
        >
          async
        </span>
        <span
          className="word"
          style={{ "--delay": "1s", "--x": "20%", "--y": "70%" }}
        >
          console.log
        </span>
        <span
          className="word"
          style={{ "--delay": "3s", "--x": "75%", "--y": "60%" }}
        >
          import
        </span>
        <span
          className="word"
          style={{ "--delay": "1.5s", "--x": "40%", "--y": "20%" }}
        >
          class
        </span>
        <span
          className="word"
          style={{ "--delay": "4s", "--x": "60%", "--y": "80%" }}
        >
          return
        </span>
        <span
          className="word"
          style={{ "--delay": "0.5s", "--x": "90%", "--y": "45%" }}
        >
          const
        </span>
        <span
          className="word"
          style={{ "--delay": "2.5s", "--x": "15%", "--y": "50%" }}
        >
          array.map
        </span>
        <span
          className="word"
          style={{ "--delay": "3.5s", "--x": "50%", "--y": "10%" }}
        >
          useState
        </span>
        <span
          className="word"
          style={{ "--delay": "1.8s", "--x": "80%", "--y": "75%" }}
        >
          API
        </span>
        <span
          className="word"
          style={{ "--delay": "2.8s", "--x": "25%", "--y": "85%" }}
        >
          JSON
        </span>
        <span
          className="word"
          style={{ "--delay": "0.8s", "--x": "95%", "--y": "30%" }}
        >
          forEach
        </span>
        <span
          className="word"
          style={{ "--delay": "4.5s", "--x": "35%", "--y": "90%" }}
        >
          git push
        </span>
        <span
          className="word"
          style={{ "--delay": "1.2s", "--x": "70%", "--y": "15%" }}
        >
          await
        </span>
        <span
          className="word"
          style={{ "--delay": "3.8s", "--x": "5%", "--y": "65%" }}
        >
          merge
        </span>
        <span
          className="word"
          style={{ "--delay": "2.2s", "--x": "55%", "--y": "40%" }}
        >
          debug
        </span>
        <span
          className="word"
          style={{ "--delay": "4.2s", "--x": "85%", "--y": "85%" }}
        >
          deploy
        </span>
        <span
          className="word"
